#!/usr/bin/env bash
# One-time preparation for the self-hosted Multica server.
#
# There is very little to do here. The JWT secret and the database password are
# generated by the stack itself, in Secrets Manager, so nothing has to be
# created by hand before a first deploy. What is left is the CDK toolkit and
# one optional value a human has to supply.
#
# Usage: ./scripts/selfhost-setup.sh
set -euo pipefail

cd "$(dirname "$0")/.."

PARAM_PREFIX="${MULTICA_SELFHOST_PARAM_PREFIX:-/multica/self-host}"

command -v aws >/dev/null || { echo "aws CLI is required" >&2; exit 1; }

account="$(aws sts get-caller-identity --query Account --output text)"
region="${AWS_REGION:-$(aws configure get region)}"
if [ -z "${region}" ]; then
  echo "No region configured. Set AWS_REGION or run 'aws configure'." >&2
  exit 1
fi

echo "Account: ${account}"
echo "Region:  ${region}"
echo

echo "==> Bootstrapping the CDK toolkit"
npx cdk bootstrap "aws://${account}/${region}"

echo
echo "Optional: email delivery for login codes."
echo "Without it the backend prints each code to its own log, which"
echo "./scripts/selfhost-apply.sh --code reads for you."
read -rp "Store a Resend API key now? (y/N) " reply
case "${reply}" in
  y | Y)
    read -rsp "  Resend API key (input hidden): " resend_key
    echo
    if [ -n "${resend_key}" ]; then
      aws ssm put-parameter --region "${region}" --name "${PARAM_PREFIX}/resend-api-key" \
        --type SecureString --value "${resend_key}" --overwrite >/dev/null

      # Resend rejects a From address on an unverified domain, so the
      # backend's noreply@multica.ai default would send nothing at all.
      echo "  From address. Must be on a domain verified at resend.com/domains."
      echo "  Blank uses onboarding@resend.dev, which Resend delivers only to"
      echo "  the address your Resend account was opened with."
      read -rp "  From address (blank for onboarding@resend.dev): " resend_from
      if [ -n "${resend_from}" ]; then
        aws ssm put-parameter --region "${region}" --name "${PARAM_PREFIX}/resend-from-email" \
          --type String --value "${resend_from}" --overwrite >/dev/null
      fi
      echo "  stored"
    fi
    ;;
  *) echo "  skipped" ;;
esac

echo
echo "Done. Deploy with:"
echo "  ./scripts/selfhost-deploy.sh you@example.com,teammate@example.com"
